RESULT_STRINGS.ko.createdCount = (done: number,total: number) => `\ud074\ub9bd ${done}/${total}\uac1c \uc0dd\uc131 \uc644\ub8cc`;
function savedDraftResults(jobs: any[], projectId: string) {
  return jobs.filter(j=>j?.projectId === projectId && !j.dismissed && Array.isArray(j.built) && j.built.some((d: any)=>!d?.deleted && (d?.draftId || d?.error)))
    .sort((a,b)=>String(b.created || b.updated || "").localeCompare(String(a.created || a.updated || "")) || String(b.id || "").localeCompare(String(a.id || "")));
}
function latestDraftResult(jobs: any[], projectId: string) { return savedDraftResults(jobs,projectId)[0] || null; }
function resultJobLabel(job: any, lang: string, R: any) {
  const sourceName=String(job.title || job.resourceName || "");
  const source=sourceName && !/^[\w-]{11}\.(mp4|mov|mkv|webm)$/i.test(sourceName)
    ? sourceName : String(job.built?.find((d: any)=>d?.headline1 && !d.deleted)?.headline1 || R.untitled);
  const date=new Date(job.created || job.updated);
  const stamp=Number.isNaN(date.getTime()) ? R.unknownDate : new Intl.DateTimeFormat(lang === "ko" ? "ko-KR" : "en-US",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit",hour12:false}).format(date);
  return `${source} · ${stamp} · ${R.title(job.built.filter((d: any)=>d && !d.deleted && clipReady(d)).length)}`;
}
// A fixed rubric and deterministic mean keep the displayed score independent of AI arithmetic.
const CLIP_SCORE_PROMPT = `For each clip, assess only the selected transcript content, not visuals, audio delivery or predicted views.
Return assessment: {hook:0..10, flow:0..10, payoff:0..10, reason:"one short explanation in the user's language"}.
Use integer scores. Hook: does the opening establish a clear reason to keep watching? Flow: does the sequence make sense without missing context or abrupt jumps? Payoff: does it deliver an answer, insight or conclusion?
Anchors for each criterion: 0-2 absent or incoherent; 3-4 weak; 5-6 adequate; 7-8 strong; 9-10 exceptional with clear evidence in the selected passage. Do not give high scores just to fill the requested count. Ground the reason in this clip's opening, progression and ending.`;
function clipAssessment(value: any) {
  if (!value || !["hook","flow","payoff"].every(k=>Number.isInteger(value[k]) && value[k]>=0 && value[k]<=10) || typeof value.reason!=="string" || !value.reason.trim()) return null;
  return {hook:value.hook,flow:value.flow,payoff:value.payoff,reason:value.reason.trim().slice(0,600),
    overall:Math.round((value.hook+value.flow+value.payoff)/3*10)/10,rubricVersion:1};
}
function rankDrafts(drafts: any[]) {
  return [...drafts].sort((a,b)=>(clipAssessment(b.assessment)?.overall ?? -1)-(clipAssessment(a.assessment)?.overall ?? -1));
}
// Cache snapshots independently of the timeline: opening a draft never refreshes its saved image.
// Folder identity belongs to the run, not to an individual clip or retry.
function withoutRunSuffix(name: string, runId: string) {
  const suffix = ` · ${runId}`;
  return name.endsWith(suffix) ? name.slice(0, -suffix.length) : name;
}
function runFolderName(job: any) {
  const title = String(job.title || job.resourceName || "Shorts").replace(/[\/\\\x00-\x1f]/g, " ").trim().slice(0, 64);
  const created = new Date(job.created);
  const stamp = Number.isFinite(created.getTime()) ? created.toLocaleString("sv-SE").slice(0, 16) : "";
  return `\uc1fc\uce20 · ${title} · ${stamp} · ${job.id}`;
}
function runFolderScript(projectId: string, folderId: string | undefined, name: string) {
  return `const project = selects.project(${JSON.stringify(projectId)});
const inventory = await project.readFootage();
const folder = inventory.folders.find(f => f.folderId === ${JSON.stringify(folderId || null)})
  || inventory.folders.find(f => f.name === ${JSON.stringify(name)});
return folder ? {folderId: folder.folderId} : await project.createFolder({name: ${JSON.stringify(name)}});`;
}
// A run resumes from its saved record, never from a list entry that later edits (such as deletion) left behind.
async function latestSavedJob(store: any, job: any) {
  if (!job?.id || !store?.get) return job;
  try { return (await store.get("jobs", job.id)) ?? job; } catch { return job; }
}
async function ensureRunFolder(job: any, script: any, persist: any) {
  const folderName = job.folderName || runFolderName(job);
  // Save the deterministic name first, so a crash after creation can recover it.
  await persist({folderName});
  const result = await script(runFolderScript(job.projectId, job.folderId, folderName), "Prepare shorts run folder", true);
  if (!result?.folderId) throw new Error("Could not create the shorts run folder");
  await persist({folderId: result.folderId});
  // Keep the recovery name private; only rename names created by this run.
  const displayName = withoutRunSuffix(folderName, job.id);
  await script(`const p = selects.project(${JSON.stringify(job.projectId)});
const folder = (await p.readFootage()).folders.find(f => f.folderId === ${JSON.stringify(result.folderId)});
if (folder?.name === ${JSON.stringify(folderName)}) await p.renameFolder({folderId: folder.folderId, name: ${JSON.stringify(displayName)}});
return true;`, "Name shorts run folder", true);
  return result.folderId;
}
function findRunDraftScript(projectId:string,name:string) {
  return `const p=selects.project(${JSON.stringify(projectId)});
const hit=(await p.readFootage()).drafts.find(d=>d.name===${JSON.stringify(name)});
if(!hit)return null;
const m=await selects.draft(hit.sequenceId).meta();
return {draftId:hit.sequenceId,seconds:Math.round(m.durationSeconds*10)/10};`;
}
async function moveRunDrafts(projectId: string, folderId: string, draftIds: string[], script: any, runId?: string) {
  const ids = [...new Set(draftIds.filter(Boolean))];
  if (!ids.length) return;
  const result = await script(`return await selects.project(${JSON.stringify(projectId)}).moveToFolder(${JSON.stringify({targetFolderId: folderId, draftIds: ids})});`, "Place shorts in run folder", true);
  if (!result || result.skipped?.length) throw new Error("Some shorts could not be placed in the run folder. Resume to retry.");
  if (runId) await script(`for (const id of ${JSON.stringify(ids)}) {
const d = selects.draft(id); const m = await d.meta(); const suffix = ${JSON.stringify(" · " + runId)};
if (m.name.endsWith(suffix)) { await d.setName(m.name.slice(0, -suffix.length)); await d.commitAll("Set clip display name"); }
} return true;`, "Name shorts drafts", true);
}

function thumbnailPath(jobId: string, draftId: string) {
  if (![jobId,draftId].every(id => /^[a-zA-Z0-9_-]+$/.test(id))) throw new Error("Invalid thumbnail identifier");
  return `thumbnails/${jobId}/${draftId}.jpg`;
}
// Heavy local operations share a FIFO; model calls never enter this queue.
function createWorkQueue() {
  let tail: Promise<any> = Promise.resolve();
  return <T,>(task: () => Promise<T>): Promise<T> => {
    const result = tail.then(task);
    tail = result.catch(() => {});
    return result;
  };
}
const visualWork = createWorkQueue();
const PROGRESS_SAVE_MS = 5000;
// A burst of progress saves becomes one save per window.
function throttledSave(save: () => Promise<void>, ms: number, onError: (e: any) => void) {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return {
    soon() {
      if (timer) return;
      timer = setTimeout(() => { timer = null; save().catch(onError); }, ms);
    },
    cancel() {
      if (timer) clearTimeout(timer);
      timer = null;
    },
  };
}
function createReframeWork(check: () => void = () => {}) {
  const faces = createWorkQueue();
  const cache = new Map<string,Promise<any>>();
  return {
    check,
    face(key: string, task: () => Promise<any>) {
      const existing = cache.get(key);
      if (existing) return existing;
      const result = faces(async()=>{check();return task();});
      cache.set(key,result);
      result.catch(() => { if(cache.get(key) === result) cache.delete(key); });
      return result;
    },
  };
}
// Bridge silence-removal gaps without repeatedly decoding/model-loading each fragment.
function cameraFaceRanges(segments: number[][]): number[][] {
  const out: number[][] = [];
  for (const range of faceRanges(segments,Infinity,0)) {
    const previous = out[out.length-1];
    if (previous && range[0]-previous[1] <= 1) previous[1]=Math.max(previous[1],range[1]);
    else out.push(range.slice());
  }
  return out;
}

async function readDraftThumbnail(sdk: any, projectId: string, draftId: string) {
  const snapshot = await sdk.call("getDraftMediaSnapshot",projectId,draftId);
  const ends = (snapshot?.clips || []).filter((c: any)=>c.trackKind === "main").map((c: any)=>c.endFrame).filter(Number.isFinite);
  const end = ends.length ? Math.max(...ends) : 0;
  if (!(snapshot?.fps > 0) || end <= 0) return null;
  const frameNumber = Math.min(Math.round(snapshot.fps),Math.max(0,Math.ceil(end)-1));
  const core = await sdk.call("getDraftCore",draftId);
  if (!core?.owner || core.owner.projectId !== projectId) throw new Error("Draft project mismatch");
  const image = await visualWork(() => sdk.call("captureVisualFrames",{
    owner:core.owner,sequenceId:draftId,sequenceJson:core.sequenceJson,generatorJsons:core.generatorJsons,
    coordinate:"resolved",frames:[{frameNumber,view:"timeline_composite"}],includeOverlays:true,
  }));
  if (image?.mimeType !== "image/jpeg" || typeof image.data !== "string" || image.data.length > 4000000 || !image.data) return null;
  return "data:image/jpeg;base64," + image.data;
}
const thumbnailRequests = new Map<string,Promise<any>>();
function loadDraftThumbnail(store: any, sdk: any, projectId: string, jobId: string, draftId: string, refresh = false): Promise<any> {
  const key = JSON.stringify([store?.root,projectId,jobId,draftId]);
  const existing = thumbnailRequests.get(key);
  if (existing) return existing;
  const request = captureOrReadThumbnail(store,sdk,projectId,jobId,draftId,refresh).finally(()=>thumbnailRequests.delete(key));
  thumbnailRequests.set(key,request);
  return request;
}
async function captureOrReadThumbnail(store: any, sdk: any, projectId: string, jobId: string, draftId: string, refresh = false) {
  const relative = thumbnailPath(jobId,draftId);
  const path = store?.fs && store.join(store.root,relative);
  if (!refresh && path && await store.exists(path)) {
    const bytes = await store.fs.readFile(path);
    if (bytes.length && bytes.length <= 3000000) return {data:"data:image/jpeg;base64,"+toBase64(bytes),thumbnailPath:relative};
  }
  const data = await readDraftThumbnail(sdk,projectId,draftId);
  if (!data) return null;
  if (path) await store.fs.writeFile(path,fromBase64(data.split(",")[1]));
  return {data,thumbnailPath:path ? relative : null};
}
function DraftThumbnail({sdk,store,jobId,projectId,draftId,R,hold}: any) {
  const [data,setData]=React.useState("");
  React.useEffect(()=>{
    let live=true;setData("");
    // While the run still owes this clip a fresh preview, a card-side capture would
    // jump the visual queue (or show a stale image after reframing).
    if (!hold && sdk && projectId && jobId && draftId) loadDraftThumbnail(store,sdk,projectId,jobId,draftId).then(image=>{if(live)setData(image?.data||"");}).catch(()=>{});
    return ()=>{live=false;};
  },[sdk,store,jobId,projectId,draftId,hold]);
  const url=useBlobUrl(data);
  return <div className="clip-result-thumbnail" aria-label={R.thumbnail}>
    {url ? <img src={url} alt="" style={{width:"100%",height:"100%",objectFit:"contain",display:"block"}}/> : <small>{hold ? R.thumbnailPending : R.noThumbnail}</small>}
  </div>;
}
function ScoreTooltip({assessment,R}: any) {
  const [open,setOpen] = React.useState(false);
  const [above,setAbove] = React.useState(false);
  const id = React.useId();
  const show = (event: any) => {
    const rect = event.currentTarget.getBoundingClientRect();
    setAbove(window.innerHeight - rect.bottom < 220 && rect.top > 220);
    setOpen(true);
  };
  return <span style={{position:"relative",display:"inline-flex"}} onMouseEnter={show} onMouseLeave={()=>setOpen(false)}>
    <button type="button" aria-label={R.scoreReason} aria-describedby={open ? id : undefined}
      onFocus={show} onBlur={()=>setOpen(false)} onClick={show}
      onKeyDown={event=>{if(event.key === "Escape"){setOpen(false);event.stopPropagation();}}}
      style={{display:"inline-flex",alignItems:"center",justifyContent:"center",width:14,height:14,minWidth:0,minHeight:0,padding:0,border:0,borderRadius:0,boxShadow:"none",background:"none",color:"var(--panel-muted-fg)",lineHeight:1,cursor:"help",flexShrink:0}}>
      <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.2" aria-hidden="true">
        <circle cx="8" cy="8" r="6.2"/><path d="M8 7v4"/><circle cx="8" cy="4.8" r="0.7" fill="currentColor" stroke="none"/>
      </svg>
    </button>
    {open && <span id={id} role="tooltip" style={{position:"absolute",right:0,...(above ? {bottom:"100%"} : {top:"100%"}),zIndex:20,
      width:"min(260px, calc(100vw - 32px))",boxSizing:"border-box",padding:12,border:"1px solid var(--panel-border)",borderRadius:8,
      background:"var(--background, #202020)",color:"var(--panel-fg)",boxShadow:"0 4px 16px #0005",textAlign:"left",fontSize:12,lineHeight:1.5,display:"flex",flexDirection:"column",gap:8}}>
      <span>{assessment.reason}</span>
    </span>}
  </span>;
}

