  const color=(v:any)=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);
  if(t.fontId!==undefined&&!['system',...COVER_FONTS.map(f=>f.id)].includes(t.fontId))throw Error('Invalid thumbnail font');
